import{_ as s,l as i,o as e,c as n,v as o,p as l,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"容器逃逸","description":"","frontmatter":{"title":"容器逃逸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/container-escape.md","filePath":"cs/container-escape.md","lastUpdated":1789023840000}'),h={name:"cs/container-escape.md"};function E(m,a,u,_,B,A){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="容器逃逸" tabindex="-1">容器逃逸 <a class="header-anchor" href="#容器逃逸" aria-label="Permalink to &quot;容器逃逸&quot;">​</a></h1><div class="epigraph"><p>容器用命名空间与 cgroup 切片同一内核。逃逸常走挂载、特权、有缺陷的系统调用或运行时。比 VM 更轻，也更依赖内核正确与禁止特权容器。</p><footer>—— 据 Linux namespaces/cgroups 文档；OCI 运行时规范；对照[隔离与沙箱](/cs/isolation-sandbox)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/vm-escape">VM 逃逸</a>有独立内核。缺口是<strong>共享内核的薄盒</strong>。本课讲运行时合同：非特权、只读根、seccomp，不给逃逸步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>--privileged、docker.sock 挂载、旧 runc。缺口是：默认非特权、只读、用户命名空间、最小镜像。</p><h3 id="k8s" tabindex="-1">K8s <a class="header-anchor" href="#k8s" aria-label="Permalink to &quot;K8s&quot;">​</a></h3><p>Pod 安全策略与准入是同一合同的编排层。</p><p><span class="marginnote">runc CVE 仅作窗口点名。禁止逃逸教程。隐私单元下一课从差分隐私起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 VM。列出禁止项。系统与硬件课序封口，下一课序隐私。</p>',12)),(e(),l(p,null,{default:t(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTR%5B%22%E5%AE%B9%E5%99%A8%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20KERN%5B%22%E5%90%8C%E4%B8%80%E5%86%85%E6%A0%B8%22%5D%0A%20%20PRIV%5B%22%E7%89%B9%E6%9D%83%E6%88%96%E5%A5%97%E6%8E%A5%E5%AD%97%E6%8C%82%E8%BD%BD%22%5D%20--%3E%20ESC%5B%22%E9%80%83%E5%88%B0%E5%AE%BF%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20POL%5B%22%E9%9D%9E%E7%89%B9%E6%9D%83%20seccomp%20%E5%8F%AA%E8%AF%BB%22%5D%20--%3E%20LIM%5B%22%E7%BC%A9%E5%B0%8F%E9%9D%A2%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>薄隔离要更严的默认。隐私课序问数据发布而非逃逸。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零逃逸配方。下一课序差分隐私。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VM 有客核；容器共享内核。</li><li>特权与运行时套接字是经典面。</li><li>默认非特权加 seccomp。</li><li>下一课序：差分隐私。</li><li>出处：Linux namespaces；OCI；<a href="/cs/isolation-sandbox">isolation-sandbox</a>。</li></ul>',8))])}const x=s(h,[["render",E]]);export{b as __pageData,x as default};
